import java.io.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;
public class ClassIndex {
 static String quote(String value){StringBuilder out=new StringBuilder("\"");for(char c:value.toCharArray()){if(c=='"'||c=='\\')out.append('\\').append(c);else if(c<32)out.append(String.format("\\u%04x",(int)c));else out.append(c);}return out.append('"').toString();}
 static String digest(String s){try{return java.util.Base64.getEncoder().encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8")));}catch(Exception e){throw new RuntimeException(e);}}
 static String shape(String s){return s.replaceAll("L[^;]+;","L;");}
 public static void main(String[] args)throws Exception{try(JarFile jar=new JarFile(args[0]);PrintWriter out=new PrintWriter(args[1],"UTF-8")){out.print("[");boolean first=true;Enumeration<JarEntry> entries=jar.entries();while(entries.hasMoreElements()){JarEntry e=entries.nextElement();if(!e.getName().endsWith(".class"))continue;final List<String> methods=new ArrayList<>(),fields=new ArrayList<>(),strings=new ArrayList<>();final String[] header={""};try(InputStream in=jar.getInputStream(e)){new ClassReader(in).accept(new ClassVisitor(Opcodes.ASM9){public void visit(int v,int a,String n,String s,String parent,String[] interfaces){header[0]="{\"name\":"+quote(n)+",\"parent\":"+quote(parent==null?"":parent)+",\"interfaces\":["+String.join(",",Arrays.stream(interfaces).map(ClassIndex::quote).toArray(String[]::new))+"]";}
 public FieldVisitor visitField(int a,String n,String d,String s,Object val){fields.add("{\"name\":"+quote(n)+",\"desc\":"+quote(d)+",\"access\":"+a+"}");return null;}
 public MethodVisitor visitMethod(int a,String n,String d,String s,String[] ex){return new MethodVisitor(Opcodes.ASM9){StringBuilder body=new StringBuilder();List<String> refs=new ArrayList<>();void op(int o){body.append(o).append(',');}public void visitInsn(int o){op(o);}public void visitIntInsn(int o,int x){op(o);body.append(x);}public void visitVarInsn(int o,int x){op(o);body.append(x);}public void visitTypeInsn(int o,String t){op(o);}public void visitFieldInsn(int o,String owner,String name,String desc){op(o);body.append(shape(desc));refs.add("{\"owner\":"+quote(owner)+",\"name\":"+quote(name)+",\"desc\":"+quote(desc)+"}");}public void visitMethodInsn(int o,String owner,String name,String desc,boolean itf){op(o);body.append(shape(desc));if(owner.startsWith("java/"))body.append(owner).append(name);}public void visitJumpInsn(int o,Label l){op(o);}public void visitLdcInsn(Object v){op(18);if(v instanceof String){strings.add(quote((String)v));body.append(v);}else if(v instanceof Number)body.append(v);}public void visitIincInsn(int x,int v){op(132);body.append(x).append(':').append(v);}public void visitEnd(){methods.add("{\"name\":"+quote(n)+",\"desc\":"+quote(d)+",\"access\":"+a+",\"hash\":"+quote(digest(body.toString()))+",\"size\":"+body.length()+",\"refs\":["+String.join(",",refs)+"]}");}};}
 },ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}if(!first)out.print(",");first=false;out.print(header[0]+",\"strings\":["+String.join(",",new LinkedHashSet<>(strings))+"],\"fields\":["+String.join(",",fields)+"],\"methods\":["+String.join(",",methods)+"]}");}out.print("]");}}
}
